+
+static bool wifi_ap_tx_slot(const void *address, unsigned int *index)
+{
+  unsigned int i;
+
+  for (i = 0; i < CONFIG_BK7258_WIFI_TX_SLOTS; i++)
+    {
+      const uint8_t *cpdu = g_wifi.tx[i].bytes + 4 +
+                            sizeof(struct bk7258_wifi_pbuf);
+      if (address == cpdu)
+        {
+          *index = i;
+          return true;
+        }
+    }
+
+  return false;
+}
