+static int wifi_send_node(uint8_t channel, uint32_t head, uint32_t tail,
+                          uint8_t count)
+{
+  struct bk7258_mb_wire_message message;
+  struct bk7258_wifi_ipc_node node;
+
+  memset(&node, 0, sizeof(node));
+  node.head = head;
+  node.tail = tail;
+  node.channel = channel;
+  node.num = count;
+  memcpy(&message, &node, sizeof(message));
+  return bk7258_mailbox_send_wire(channel, &message, NULL, NULL);
+}
