+static struct bk7258_wifi_cmd_slot *wifi_command_alloc(void)
+{
+  unsigned int i;
+
+  for (i = 0; i < BK7258_WIFI_CMD_SLOTS; i++)
+    {
+      if (!g_wifi.commands[i].busy)
+        {
+          g_wifi.commands[i].busy = true;
+          *(uint32_t *)g_wifi.commands[i].bytes = BK7258_WIFI_CMD_PATTERN_BUSY;
+          return &g_wifi.commands[i];
+        }
+    }
+
+  return NULL;
+}
+
+static void wifi_command_free(struct bk7258_wifi_cmd_slot *slot)
+{
+  if (slot != NULL)
+    {
+      *(uint32_t *)slot->bytes = BK7258_WIFI_CMD_PATTERN_FREE;
+      slot->busy = false;
+    }
+}
+
+static struct bk7258_wifi_cmd_slot *wifi_command_from_address(uint32_t address)
+{
+  unsigned int i;
+
+  for (i = 0; i < BK7258_WIFI_CMD_SLOTS; i++)
+    {
+      if (address == (uint32_t)(uintptr_t)(g_wifi.commands[i].bytes + 4))
+        {
+          return &g_wifi.commands[i];
+        }
+    }
+
+  return NULL;
+}
+
+static int wifi_command(uint16_t command, const void *payload, uint16_t length,
+                        void *result, uint16_t result_size)
+{
+  struct bk7258_wifi_cmd_slot *slot;
+  struct bk7258_wifi_cpdu *cpdu;
+  struct bk7258_wifi_msg_hdr *header;
+  struct bk7258_wifi_ipc_node node;
+  irqstate_t flags;
+  uint16_t sequence;
+  int ret;
+
+  if (length > BK7258_WIFI_CMD_SLOT_SIZE - 4 - sizeof(*cpdu) -
+              sizeof(*header) || !bk7258_mailbox_link_ready())
+    {
+      return -EINVAL;
+    }
+
+  nxmutex_lock(&g_wifi.lock);
+  if (g_wifi.waiting_id != 0)
+    {
+      nxmutex_unlock(&g_wifi.lock);
+      return -EBUSY;
+    }
+
+  slot = wifi_command_alloc();
+  if (slot == NULL)
+    {
+      nxmutex_unlock(&g_wifi.lock);
+      return -ENOMEM;
+    }
+
+  cpdu = (struct bk7258_wifi_cpdu *)(slot->bytes + 4);
+  header = (struct bk7258_wifi_msg_hdr *)(cpdu + 1);
+  sequence = ++g_wifi.command_sequence;
+  memset(cpdu, 0, sizeof(*cpdu));
+  cpdu->length = sizeof(*cpdu) + sizeof(*header) + length;
+  cpdu->type_dst = 0;
+  header->cmd_id = command;
+  header->cmd_sn = sequence;
+  header->length = length;
+  if (payload != NULL && length != 0)
+    {
+      memcpy(header + 1, payload, length);
+    }
+
+  memset(&node, 0, sizeof(node));
+  node.head = (uint32_t)(uintptr_t)cpdu;
+  node.tail = node.head;
+  node.channel = BK7258_WIFI_CMD_RX_CHANNEL;
+  node.num = 1;
+  memcpy((void *)&flags, &flags, sizeof(flags));
+  g_wifi.waiting_id = command + BK7258_WIFI_CFM_OFFSET;
+  g_wifi.waiting_sequence = sequence;
+  g_wifi.command_result = -ETIMEDOUT;
+  g_wifi.command_length = 0;
+  nxmutex_unlock(&g_wifi.lock);
+
+  ret = wifi_send_node(BK7258_WIFI_CMD_TX_CHANNEL, node.head, node.tail, 1);
+  if (ret < 0)
+    {
+      nxmutex_lock(&g_wifi.lock);
+      g_wifi.waiting_id = 0;
+      wifi_command_free(slot);
+      nxmutex_unlock(&g_wifi.lock);
+      return ret;
+    }
+
+  ret = nxsem_tickwait_uninterruptible(&g_wifi.command_sem,
+                                       WIFI_CMD_TIMEOUT);
+  nxmutex_lock(&g_wifi.lock);
+  if (ret < 0 || g_wifi.command_result < 0)
+    {
+      ret = ret < 0 ? ret : g_wifi.command_result;
+    }
+  else
+    {
+      ret = g_wifi.command_result;
+      if (result != NULL && result_size != 0)
+        {
+          uint16_t copy = g_wifi.command_length < result_size ?
+                          g_wifi.command_length : result_size;
+          memcpy(result, g_wifi.command_data, copy);
+        }
+    }
+  g_wifi.waiting_id = 0;
+  wifi_command_free(slot);
+  nxmutex_unlock(&g_wifi.lock);
+  return ret;
+}
+
+static void wifi_carrier(bool on)
+{
+  if (g_wifi.carrier != on)
+    {
+      g_wifi.carrier = on;
+      if (on)
+        {
+          netdev_lower_carrier_on(&g_wifi.lower);
+        }
+      else
+        {
+          netdev_lower_carrier_off(&g_wifi.lower);
+        }
+    }
+}
