+static void wifi_release_cpdu(uint32_t address)
+{
+  struct bk7258_wifi_cpdu *cpdu;
+
+  if (!wifi_cp_ptr(address, sizeof(*cpdu)))
+    {
+      return;
+    }
+
+  cpdu = (struct bk7258_wifi_cpdu *)(uintptr_t)address;
+  cpdu->flags |= 1u;
+  __asm__ volatile("dmb sy" ::: "memory");
+  (void)wifi_send_node(BK7258_WIFI_DATA_TX_CHANNEL, address, address, 1);
+}
+
+static bool wifi_rx_packet(uint32_t cpdu_address,
+                           struct bk7258_wifi_rx_packet *packet)
+{
+  struct bk7258_wifi_cpdu cpdu;
+  struct bk7258_wifi_pbuf pbuf;
+  uint32_t pbuf_address;
+  uint32_t payload;
+
+  if (!wifi_cp_ptr(cpdu_address, sizeof(cpdu)))
+    {
+      return false;
+    }
+
+  memcpy(&cpdu, (const void *)(uintptr_t)cpdu_address, sizeof(cpdu));
+  if ((cpdu.flags & 1u) != 0 || cpdu.length < sizeof(cpdu) ||
+      cpdu.length > sizeof(cpdu) + BK7258_WIFI_MAX_FRAME)
+    {
+      return false;
+    }
+
+  pbuf_address = cpdu_address - sizeof(struct bk7258_wifi_pbuf);
+  if (!wifi_cp_ptr(pbuf_address, sizeof(pbuf)))
+    {
+      return false;
+    }
+  memcpy(&pbuf, (const void *)(uintptr_t)pbuf_address, sizeof(pbuf));
+  payload = pbuf.payload;
+  if (!wifi_cp_ptr(payload, pbuf.len) || pbuf.len == 0 ||
+      pbuf.len > BK7258_WIFI_MAX_FRAME || pbuf.tot_len != pbuf.len)
+    {
+      return false;
+    }
+
+  memcpy(packet->data, (const void *)(uintptr_t)payload, pbuf.len);
+  packet->length = pbuf.len;
+  return true;
+}
+
+static void wifi_process_command(uint32_t address)
+{
+  struct bk7258_wifi_event_hdr event;
+  struct bk7258_wifi_cmd_slot *slot;
+  uint8_t *base;
+
+  slot = wifi_command_from_address(address);
+  if (slot == NULL || !slot->busy ||
+      !wifi_cp_ptr(address, sizeof(struct bk7258_wifi_event_hdr)))
+    {
+      return;
+    }
+
+  base = (uint8_t *)(uintptr_t)address;
+  memcpy(&event, base, sizeof(event));
+  nxmutex_lock(&g_wifi.lock);
+  if (event.id == g_wifi.waiting_id &&
+      event.sequence == g_wifi.waiting_sequence)
+    {
+      uint16_t length = event.length;
+      if (length > sizeof(g_wifi.command_data))
+        {
+          length = sizeof(g_wifi.command_data);
+        }
+      if (length != 0)
+        {
+          memcpy(g_wifi.command_data, base + sizeof(event), length);
+        }
+      g_wifi.command_length = length;
+      g_wifi.command_result = 0;
+      nxsem_post(&g_wifi.command_sem);
+    }
+  nxmutex_unlock(&g_wifi.lock);
+}
+
+static void wifi_process_event(uint32_t address)
+{
+  struct bk7258_wifi_event_hdr event;
+  uint8_t data[64];
+  uint16_t length;
+
+  if (!wifi_cp_ptr(address, sizeof(event)))
+    {
+      return;
+    }
+  memcpy(&event, (const void *)(uintptr_t)address, sizeof(event));
+  length = event.length;
+  if (length > sizeof(data) || !wifi_cp_ptr(address + sizeof(event), length))
+    {
+      return;
+    }
+  memcpy(data, (const void *)(uintptr_t)(address + sizeof(event)), length);
+
+  if (event.id == BK7258_WIFI_EVT_IPV4_IND)
+    {
+      wifi_carrier(true);
+    }
+  else if (event.id == BK7258_WIFI_EVT_WIFI_EVENT_IND && length >= 4)
+    {
+      uint16_t event_id;
+      memcpy(&event_id, data, sizeof(event_id));
+      if (event_id == BK7258_WIFI_EVENT_CONNECTED)
+        {
+          wifi_carrier(true);
+        }
+      else if (event_id == BK7258_WIFI_EVENT_DISCONNECTED)
+        {
+          wifi_carrier(false);
+        }
+    }
+  else if (event.id == 3u)
+    {
+      wifi_carrier(false);
+    }
+  else if (event.id == 8u)
+    {
+      g_wifi.scan_running = false;
+    }
+}
+
+static void wifi_process_data(uint32_t head, uint8_t count)
+{
+  uint32_t address = head;
+  uint8_t i;
+
+  if (count == 0 || count > BK7258_WIFI_MAX_LIST)
+    {
+      return;
+    }
+
+  for (i = 0; i < count && address != 0; i++)
+    {
+      struct bk7258_wifi_cpdu cpdu;
+      struct bk7258_wifi_rx_packet packet;
+      uint32_t next;
+
+      if (!wifi_cp_ptr(address, sizeof(cpdu)))
+        {
+          break;
+        }
+      memcpy(&cpdu, (const void *)(uintptr_t)address, sizeof(cpdu));
+      next = cpdu.next;
+      if ((cpdu.flags & 1u) != 0)
+        {
+          unsigned int slot;
+          if (wifi_ap_tx_slot((const void *)(uintptr_t)address, &slot) &&
+              g_wifi.tx[slot].active)
+            {
+              netpkt_free(&g_wifi.lower, g_wifi.tx[slot].pkt, NETPKT_TX);
+              g_wifi.tx[slot].pkt = NULL;
+              g_wifi.tx[slot].active = false;
+              netdev_lower_txdone(&g_wifi.lower);
+            }
+        }
+      else if (wifi_rx_packet(address, &packet))
+        {
+          if (g_wifi.packet_count < WIFI_RX_PACKET_QUEUE)
+            {
+              g_wifi.packets[g_wifi.packet_tail] = packet;
+              g_wifi.packet_tail = (g_wifi.packet_tail + 1) %
+                                   WIFI_RX_PACKET_QUEUE;
+              g_wifi.packet_count++;
+            }
+        }
+      wifi_release_cpdu(address);
+      address = next;
+    }
+}
+
+static int wifi_rx_callback(const struct bk7258_mb_wire_message *message,
+                            uint8_t *ack_flags, void *arg)
+{
+  struct bk7258_wifi_ipc_node node;
+
+  (void)ack_flags;
+  (void)arg;
+  memcpy(&node, message, sizeof(node));
+  if (node.num == 0 || node.num > BK7258_WIFI_MAX_LIST)
+    {
+      return -EINVAL;
+    }
+
+  nxmutex_lock(&g_wifi.lock);
+  if (g_wifi.node_count == WIFI_RX_NODE_QUEUE)
+    {
+      nxmutex_unlock(&g_wifi.lock);
+      return -EAGAIN;
+    }
+  g_wifi.nodes[g_wifi.node_tail].node = node;
+  g_wifi.node_tail = (g_wifi.node_tail + 1) % WIFI_RX_NODE_QUEUE;
+  g_wifi.node_count++;
+  nxmutex_unlock(&g_wifi.lock);
+  wifi_signal_worker();
+  return OK;
+}
+
+static int wifi_worker(int argc, char **argv)
+{
+  (void)argc;
+  (void)argv;
+  for (;;)
+    {
+      struct bk7258_wifi_ipc_node node;
+
+      nxsem_tickwait_uninterruptible(&g_wifi.work_sem, WIFI_WORK_INTERVAL);
+      for (;;)
+        {
+          nxmutex_lock(&g_wifi.lock);
+          if (g_wifi.node_count == 0)
+            {
+              nxmutex_unlock(&g_wifi.lock);
+              break;
+            }
+          node = g_wifi.nodes[g_wifi.node_head].node;
+          g_wifi.node_head = (g_wifi.node_head + 1) % WIFI_RX_NODE_QUEUE;
+          g_wifi.node_count--;
+          nxmutex_unlock(&g_wifi.lock);
+
+          if (node.channel == BK7258_WIFI_CMD_RX_CHANNEL)
+            {
+              wifi_process_command(node.head);
+              wifi_process_event(node.head);
+            }
+          else if (node.channel == BK7258_WIFI_DATA_RX_CHANNEL)
+            {
+              wifi_process_data(node.head, node.num);
+              if (g_wifi.packet_count != 0)
+                {
+                  netdev_lower_rxready(&g_wifi.lower);
+                }
+            }
+        }
+    }
+  return OK;
+}
+
+static int wifi_ifup(struct netdev_lowerhalf_s *dev)
+{
+  (void)dev;
+  return OK;
+}
+
+static int wifi_ifdown(struct netdev_lowerhalf_s *dev)
+{
+  wifi_carrier(false);
+  (void)wifi_command(BK7258_WIFI_CMD_DISCONNECT, NULL, 0, NULL, 0);
+  (void)dev;
+  return OK;
+}
+
+static int wifi_transmit(struct netdev_lowerhalf_s *dev, netpkt_t *pkt)
+{
+  unsigned int i;
+  unsigned int length = netpkt_getdatalen(dev, pkt);
+  struct bk7258_wifi_tx_slot *tx = NULL;
+  struct bk7258_wifi_pbuf *pbuf;
+  struct bk7258_wifi_cpdu *cpdu;
+  uint8_t *payload;
+  int ret;
+
+  if (length == 0 || length > BK7258_WIFI_MAX_FRAME || !g_wifi.carrier)
+    {
+      return -ENETDOWN;
+    }
+  for (i = 0; i < CONFIG_BK7258_WIFI_TX_SLOTS; i++)
+    {
+      if (!g_wifi.tx[i].active)
+        {
+          tx = &g_wifi.tx[i];
+          break;
+        }
+    }
+  if (tx == NULL)
+    {
+      return -EBUSY;
+    }
+
+  pbuf = (struct bk7258_wifi_pbuf *)(tx->bytes + 4);
+  cpdu = (struct bk7258_wifi_cpdu *)(pbuf + 1);
+  payload = tx->bytes + 4 + sizeof(*pbuf) + BK7258_WIFI_TX_HEADROOM;
+  memset(pbuf, 0, sizeof(*pbuf));
+  pbuf->payload = (uint32_t)(uintptr_t)payload;
+  pbuf->len = length;
+  pbuf->tot_len = length;
+  pbuf->type_internal = WIFI_PBUF_TYPE_RAM;
+  pbuf->ref = 1;
+  memset(cpdu, 0, sizeof(*cpdu));
+  cpdu->length = sizeof(*cpdu) + length;
+  cpdu->type_dst = 2u;
+  ret = netpkt_copyout(dev, payload, pkt, length, 0);
+  if (ret < 0)
+    {
+      return ret;
+    }
+  tx->pkt = pkt;
+  tx->active = true;
+  ret = wifi_send_node(BK7258_WIFI_DATA_TX_CHANNEL, (uint32_t)(uintptr_t)cpdu,
+                       (uint32_t)(uintptr_t)cpdu, 1);
+  if (ret < 0)
+    {
+      tx->active = false;
+      tx->pkt = NULL;
+    }
+  return ret;
+}
+
+static netpkt_t *wifi_receive(struct netdev_lowerhalf_s *dev)
+{
+  netpkt_t *pkt;
+  struct bk7258_wifi_rx_packet *packet;
+
+  nxmutex_lock(&g_wifi.lock);
+  if (g_wifi.packet_count == 0)
+    {
+      nxmutex_unlock(&g_wifi.lock);
+      return NULL;
+    }
+  packet = &g_wifi.packets[g_wifi.packet_head];
+  pkt = netpkt_alloc(dev, NETPKT_RX);
+  if (pkt != NULL)
+    {
+      netpkt_copyin(dev, pkt, packet->data, packet->length, 0);
+      g_wifi.packet_head = (g_wifi.packet_head + 1) % WIFI_RX_PACKET_QUEUE;
+      g_wifi.packet_count--;
+    }
+  nxmutex_unlock(&g_wifi.lock);
+  return pkt;
+}
+
+#ifdef CONFIG_NETDEV_IOCTL
+static int wifi_ioctl(struct netdev_lowerhalf_s *dev, int command,
+                      unsigned long arg)
+{
+  struct iwreq *request = (struct iwreq *)arg;
+  (void)dev;
+  (void)request;
+  return -ENOTTY;
+}
+#endif
+
+#ifdef CONFIG_NETDEV_WIRELESS_HANDLER
+static int wifi_essid(struct netdev_lowerhalf_s *dev, struct iwreq *request,
+                      bool set)
+{
+  (void)dev;
+  if (set)
+    {
+      size_t length = request->u.essid.length;
+      if (length >= sizeof(g_wifi.ssid))
+        {
+          length = sizeof(g_wifi.ssid) - 1;
+        }
+      memcpy(g_wifi.ssid, request->u.essid.pointer, length);
+      g_wifi.ssid[length] = '\0';
+    }
+  else
+    {
+      size_t length = strlen(g_wifi.ssid) + 1;
+      memcpy(request->u.essid.pointer, g_wifi.ssid, length);
+      request->u.essid.length = length;
+    }
+  return OK;
+}
+
+static int wifi_passwd(struct netdev_lowerhalf_s *dev, struct iwreq *request,
+                       bool set)
+{
+  size_t length;
+  (void)dev;
+  if (!set)
+    {
+      request->u.encoding.length = 0;
+      return OK;
+    }
+  length = request->u.encoding.length;
+  if (length >= sizeof(g_wifi.password))
+    {
+      length = sizeof(g_wifi.password) - 1;
+    }
+  memcpy(g_wifi.password, request->u.encoding.pointer, length);
+  g_wifi.password[length] = '\0';
+  return OK;
+}
+
+static int wifi_connect(struct netdev_lowerhalf_s *dev)
+{
+  uint8_t payload[33 + 64];
+  (void)dev;
+  memset(payload, 0, sizeof(payload));
+  memcpy(payload, g_wifi.ssid, strlen(g_wifi.ssid));
+  memcpy(payload + 33, g_wifi.password, strlen(g_wifi.password));
+  return wifi_command(BK7258_WIFI_CMD_CONNECT, payload, sizeof(payload),
+                      NULL, 0);
+}
+
+static int wifi_disconnect(struct netdev_lowerhalf_s *dev)
+{
+  (void)dev;
+  wifi_carrier(false);
+  return wifi_command(BK7258_WIFI_CMD_DISCONNECT, NULL, 0, NULL, 0);
+}
+
+static int wifi_noop(struct netdev_lowerhalf_s *dev, struct iwreq *request,
+                     bool set)
+{
+  (void)dev;
+  (void)request;
+  (void)set;
+  return OK;
+}
+
+static int wifi_mode(struct netdev_lowerhalf_s *dev, struct iwreq *request,
+                     bool set)
+{
+  if (set)
+    {
+      g_wifi.mode = request->u.mode;
+    }
+  else
+    {
+      request->u.mode = g_wifi.mode;
+    }
+  (void)dev;
+  return OK;
+}
+
+static int wifi_auth(struct netdev_lowerhalf_s *dev, struct iwreq *request,
+                     bool set)
+{
+  if (set)
+    {
+      g_wifi.auth = request->u.param.value;
+    }
+  else
+    {
+      request->u.param.value = g_wifi.auth;
+    }
+  (void)dev;
+  return OK;
+}
+
+static int wifi_scan(struct netdev_lowerhalf_s *dev, struct iwreq *request,
+                     bool set)
+{
+  int ret;
+  uint8_t ssid[33];
+  (void)dev;
+  if (!set)
+    {
+      if (g_wifi.scan_running)
+        {
+          return -EAGAIN;
+        }
+      /* Full scan-result pointer ABI is not safe to expose here.  Completion
+       * therefore returns a valid empty result until a bounded result ABI is
+       * negotiated with CP. */
+      request->u.data.length = 0;
+      return OK;
+    }
+  memset(ssid, 0, sizeof(ssid));
+  ret = wifi_command(BK7258_WIFI_CMD_SCAN_WIFI, ssid, sizeof(ssid), NULL, 0);
+  if (ret == 0)
+    {
+      g_wifi.scan_running = true;
+    }
+  return ret;
+}
+
+static int wifi_range(struct netdev_lowerhalf_s *dev, struct iwreq *request)
+{
+  struct iw_range *range = (struct iw_range *)request->u.data.pointer;
+  uint8_t i;
+  (void)dev;
+  memset(range, 0, sizeof(*range));
+  range->num_frequency = 14;
+  for (i = 0; i < range->num_frequency; i++)
+    {
+      range->freq[i].m = i + 1;
+      range->freq[i].e = 0;
+    }
+  request->u.data.length = sizeof(*range);
+  return OK;
+}
+
+static const struct wireless_ops_s g_wireless_ops =
+{
+  .connect = wifi_connect,
+  .disconnect = wifi_disconnect,
+  .essid = wifi_essid,
+  .bssid = wifi_noop,
+  .passwd = wifi_passwd,
+  .mode = wifi_mode,
+  .auth = wifi_auth,
+  .freq = wifi_noop,
+  .bitrate = wifi_noop,
+  .txpower = wifi_noop,
+  .country = wifi_noop,
+  .sensitivity = wifi_noop,
+  .scan = wifi_scan,
+  .range = wifi_range
+};
+#endif
+
+static const struct netdev_ops_s g_netdev_ops =
+{
+  .ifup = wifi_ifup,
+  .ifdown = wifi_ifdown,
+  .transmit = wifi_transmit,
+  .receive = wifi_receive,
+#ifdef CONFIG_NETDEV_IOCTL
+  .ioctl = wifi_ioctl,
+#endif
+};
+
+int bk7258_wifi_initialize(void)
+{
+  int ret;
+  unsigned int i;
+
+  if (g_wifi.initialized)
+    {
+      return OK;
+    }
+  memset(&g_wifi, 0, sizeof(g_wifi));
+  nxsem_init(&g_wifi.work_sem, 0, 0);
+  nxsem_init(&g_wifi.command_sem, 0, 0);
+  nxmutex_init(&g_wifi.lock);
+  for (i = 0; i < BK7258_WIFI_CMD_SLOTS; i++)
+    {
+      *(uint32_t *)g_wifi.commands[i].bytes = BK7258_WIFI_CMD_PATTERN_FREE;
+    }
+  g_wifi.lower.ops = &g_netdev_ops;
+#ifdef CONFIG_NETDEV_WIRELESS_HANDLER
+  g_wifi.lower.iw_ops = &g_wireless_ops;
+#endif
+  g_wifi.lower.quota[NETPKT_TX] = CONFIG_BK7258_WIFI_TX_SLOTS;
+  g_wifi.lower.quota[NETPKT_RX] = WIFI_RX_PACKET_QUEUE;
+  g_wifi.lower.netdev.d_ifname[0] = 'w';
+  g_wifi.lower.netdev.d_ifname[1] = 'l';
+  g_wifi.lower.netdev.d_ifname[2] = 'a';
+  g_wifi.lower.netdev.d_ifname[3] = 'n';
+  g_wifi.lower.netdev.d_ifname[4] = '0';
+  ret = bk7258_mailbox_register_rx(BK7258_WIFI_CMD_RX_CHANNEL,
+                                   wifi_rx_callback, &g_wifi);
+  if (ret < 0)
+    {
+      return ret;
+    }
+  ret = bk7258_mailbox_register_rx(BK7258_WIFI_DATA_RX_CHANNEL,
+                                   wifi_rx_callback, &g_wifi);
+  if (ret < 0)
+    {
+      return ret;
+    }
+  g_wifi.worker = kthread_create("bk-wifi", 110, 3072, wifi_worker, NULL);
+  if (g_wifi.worker < 0)
+    {
+      return g_wifi.worker;
+    }
+  ret = netdev_lower_register(&g_wifi.lower, NET_LL_IEEE80211);
+  if (ret < 0)
+    {
+      return ret;
+    }
+  g_wifi.initialized = true;
+  return OK;
+}
