+static int wifi_scan(struct netdev_lowerhalf_s *lower,
+                     struct iwreq *request, bool set)
+{
+  uint8_t ssid[33];
+  int ret;
+
+  (void)lower;
+  if (!set)
+    {
+      if (g_wifi.scan_running)
+        {
+          return -EAGAIN;
+        }
+
+      /* The legacy result API embeds a private CP pointer.  Return a valid
+       * empty result rather than exporting an unsafe cross-core pointer. */
+      request->u.data.length = 0;
+      return OK;
+    }
+
+  memset(ssid, 0, sizeof(ssid));
+  ret = wifi_command(BK7258_WIFI_CMD_SCAN_WIFI, ssid, sizeof(ssid), NULL, 0);
+  if (ret >= 0)
+    {
